+        async encodeMimeHeader(headerName, headerValue, isMailBoxHeader) {
+          // MAILBOX_HEADERS is all lowercase.
+          headerName = headerName.toLowerCase();
+          // Return an array, even for single values.
+          if (!Array.isArray(headerValue)) {
